public class Membership{public enum Status{ACTIVE,FROZEN,EXPIRED}private final Member member;private final MembershipPlan plan;private final double fee;private Status status=Status.ACTIVE;public Membership(Member m,MembershipPlan p){if(m==null||p==null)throw new IllegalArgumentException();member=m;plan=p;fee=p.calculateFee();}public void freeze(){if(status==Status.EXPIRED)throw new IllegalStateException("Cannot freeze an Expired membership");if(status!=Status.ACTIVE)throw new IllegalStateException();status=Status.FROZEN;}public void unfreeze(){if(status==Status.EXPIRED)throw new IllegalStateException();if(status!=Status.FROZEN)throw new IllegalStateException();status=Status.ACTIVE;}public void expire(){status=Status.EXPIRED;}public boolean checkIn(){return status==Status.ACTIVE;}public double getFee(){return fee;}public Status getStatus(){return status;}public Member getMember(){return member;}public MembershipPlan getPlan(){return plan;}}